import { Table, GuidColumn, HtmlColumn, StringColumn } from '@servicenow/sdk/core'

export const sysevent_email_style = Table({
    allowWebServiceAccess: true,
    attributes: {
        synch_attachments: true,
        update_synch: true,
    },
    audit: true,
    extends: 'sys_metadata',
    label: 'Stationery',
    name: 'sysevent_email_style',
    schema: {
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        style: HtmlColumn({
            label: 'Style',
            maxLength: 65000,
        }),
        name: StringColumn({
            label: 'Name',
        }),
    },
    textIndex: true,
})
